import{_ as t,c as i,o as n,ag as a}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Identify Influencers using the TAAW","description":"","frontmatter":{"title":"Identify Influencers using the TAAW"},"headers":[],"relativePath":"general/identify-influencers-using-the-taaw.md","filePath":"general/identify-influencers-using-the-taaw.md","lastUpdated":null}'),r={name:"general/identify-influencers-using-the-taaw.md"};function s(l,e,o,d,c,u){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="identify-influencers-using-the-taaw" tabindex="-1">Identify Influencers using the TAAW <a class="header-anchor" href="#identify-influencers-using-the-taaw" aria-label="Permalink to &quot;Identify Influencers using the TAAW&quot;">​</a></h1><h2 id="using-the-taaw-to-identify-influencers-workflow" tabindex="-1">Using the TAAW to Identify Influencers: Workflow <a class="header-anchor" href="#using-the-taaw-to-identify-influencers-workflow" aria-label="Permalink to &quot;Using the TAAW to Identify Influencers: Workflow&quot;">​</a></h2><p>These steps should be used to create an OML (Order of Merit List) of influencers for Influence. If the intention is to provide strawman profiles on what influencers should be without specific names and comparisons, follow Steps 1-3. When creating an OML of influencers, Steps 4-5 should be repeated as necessary to identify suitable candidates.</p><p>The goal of these influencers should be to be influential to the target audience. If this linkage isn&#39;t there, then the influencer can not be fully assessed.</p><h3 id="step-1-assess-audience-influence-sources" tabindex="-1">Step 1: Assess Audience Influence Sources <a class="header-anchor" href="#step-1-assess-audience-influence-sources" aria-label="Permalink to &quot;Step 1: Assess Audience Influence Sources&quot;">​</a></h3><ul><li><p><strong>TAAW Sections</strong>: Step 5 (Determine Susceptibility) and Step 6 (Determine Accessibility)</p></li><li><p><strong>Questions</strong>:</p><ul><li>Who does the target audience (TA) already listen to or follow for information?</li><li>What existing organizations, key communicators, or influential figures currently influence them?</li><li>How does the TA engage with these figures or organizations, and what topics are most influential?</li></ul></li><li><p><strong>Outcome</strong>: Identify existing influencers and organizations that the TA trusts and engages with. This insight helps define credibility standards and engagement styles for creating a strawman influencer profile.</p></li></ul><h3 id="step-2-define-the-target-audience-ta" tabindex="-1">Step 2: Define the Target Audience (TA) <a class="header-anchor" href="#step-2-define-the-target-audience-ta" aria-label="Permalink to &quot;Step 2: Define the Target Audience (TA)&quot;">​</a></h3><ul><li><p><strong>TAAW Sections</strong>: Step 1 (Identify and Refine Target Audiences) and Step 3 (Identify Conditions)</p></li><li><p><strong>Questions</strong>:</p><ul><li>What is the demographic profile (age, gender, location, socioeconomic status)?</li><li>What platforms does the TA use most for information and engagement?</li><li>What motivates the TA and drives their behavior?</li></ul></li><li><p><strong>Outcome</strong>: Clearly understand the primary TA&#39;s demographic profile, platform preferences, and motivators. This data will help refine the influencer criteria to align with their needs.</p></li></ul><h3 id="step-3-identify-influencer-traits" tabindex="-1">Step 3: Identify Influencer Traits <a class="header-anchor" href="#step-3-identify-influencer-traits" aria-label="Permalink to &quot;Step 3: Identify Influencer Traits&quot;">​</a></h3><ul><li><p><strong>TAAW Sections</strong>: Step 2 (Determine Achievability), Step 3 (Identify Conditions), and Step 5 (Determine Susceptibility)</p></li><li><p><strong>Process</strong>:</p><ul><li>Determine TA&#39;s Preferred Communication Style: <ul><li>Analyze which tone, language, or visual style is most effective among the TA.</li><li>Review previous successful campaigns to understand effective messaging.</li></ul></li><li>Examine Influencer Behavioral Styles: <ul><li>Identify behavioral patterns such as humor, empathy, and authority that resonate well with the TA.</li></ul></li><li>Assess Expertise and Credibility Factors: <ul><li>Determine what authority or expertise the TA values, such as academic qualifications or professional experience.</li><li>Check past public interactions for evidence of authenticity and reliability.</li></ul></li><li>Assess Influencers&#39; Willingness to Partner with Advertisers: <ul><li>Determine past advertisement campaigns that influencers participated in.</li></ul></li></ul></li><li><p><strong>Questions</strong>:</p><ul><li>What linguistic, cultural, or behavioral styles does the TA resonate with?</li><li>What tone or content style does the TA respond to positively?</li><li>What expertise, authority, or credibility do they trust in communicators?</li></ul></li><li><p><strong>Outcome</strong>: Create a strawman profile of an ideal influencer, detailing the characteristics, communication styles, and values that will resonate with the TA. Emphasize traits like credibility, tone, and platform suitability.</p></li></ul><h3 id="step-4-search-and-list-potential-influencers" tabindex="-1">Step 4: Search and List Potential Influencers <a class="header-anchor" href="#step-4-search-and-list-potential-influencers" aria-label="Permalink to &quot;Step 4: Search and List Potential Influencers&quot;">​</a></h3><ul><li><p><strong>TAAW Sections</strong>: Step 6 (Determine Accessibility)</p></li><li><p><strong>Process</strong>:</p><ul><li>Find Prominent Public Figures and Micro-Influencers: <ul><li>Utilize social media listening tools or marketing analytics to identify figures with a significant following among the TA.</li><li>Consider mainstream celebrities and niche community influencers.</li></ul></li><li>Assess Engagement Metrics: <ul><li>Measure followers, likes, comments, shares, and mentions across platforms relevant to the TA.</li><li>Check the consistency and positivity of engagement to determine active participation.</li></ul></li><li>Use External Data Sources: <ul><li>Employ third-party data sources or marketing agencies specializing in influencer research.</li><li>Utilize influencer databases that provide filters for location, niche, and engagement rates.</li></ul></li></ul></li><li><p><strong>Questions</strong>:</p><ul><li>Who are the prominent public figures or micro-influencers within the TA&#39;s networks?</li><li>What engagement rates do these influencers have on relevant platforms?</li><li>Are there third-party analytics tools or data sources available to identify niche influencers?</li></ul></li><li><p><strong>Outcome</strong>: Generate a preliminary list of influencers based on follower count, engagement rates, and platform suitability. This provides a starting point for further evaluation.</p></li></ul><h3 id="step-5-evaluate-criteria-fit" tabindex="-1">Step 5: Evaluate Criteria Fit <a class="header-anchor" href="#step-5-evaluate-criteria-fit" aria-label="Permalink to &quot;Step 5: Evaluate Criteria Fit&quot;">​</a></h3><ul><li><p><strong>TAAW Sections</strong>: Step 4 (Identify Vulnerabilities) and Step 7 (Develop Arguments and Recommend Psychological Actions)</p></li><li><p><strong>Questions</strong>:</p><ul><li>Does the influencer have a substantial and active following among the TA?</li><li>Is their content aligned with the TA&#39;s interests, values, and cultural context?</li><li>Does the TA perceive the influencer as credible and trustworthy?</li></ul></li><li><p><strong>Outcome</strong>: Refine the list to those influencers whose messaging aligns with the TA&#39;s vulnerabilities, interests, and cultural context while maintaining credibility and high engagement.</p></li></ul><h3 id="step-6-score-and-rank-influencers" tabindex="-1">Step 6: Score and Rank Influencers <a class="header-anchor" href="#step-6-score-and-rank-influencers" aria-label="Permalink to &quot;Step 6: Score and Rank Influencers&quot;">​</a></h3><ul><li><p><strong>TAAW Sections</strong>: Step 7 (Develop Arguments and Recommend Psychological Actions)</p></li><li><p><strong>Questions</strong>:</p><ul><li>What is the engagement rate and follower count on each platform?</li><li>How consistent is the influencer&#39;s messaging with desired behavior change?</li><li>Does their content align with the TA&#39;s linguistic and cultural preferences?</li></ul></li><li><p><strong>Outcome</strong>: Develop a scoring matrix to rank influencers based on engagement, messaging alignment, and cultural suitability. The scoring will prioritize those who align with campaign objectives.</p></li></ul><h3 id="step-7-provide-influencer-oml" tabindex="-1">Step 7: Provide Influencer OML <a class="header-anchor" href="#step-7-provide-influencer-oml" aria-label="Permalink to &quot;Step 7: Provide Influencer OML&quot;">​</a></h3><p><strong>Example Influencer Comparison Table:</strong></p><p>Weights are judgments based on the mission, the area, and the TA. These can be done with any weighing concept, including linear (1, 2, 3), logarithmic (1, 3, 5), or decimals (.3, .5, .02).</p><p>Example below uses 1, 2, 3, 4, 5. A larger number means more significance. This should be analyzed per each country or TAAW and adjusted as needed.</p><table tabindex="0"><thead><tr><th>Criteria</th><th>Weight</th><th>Smith</th><th>Rahman</th><th>Garcia</th><th>Lee</th><th>Haddad</th></tr></thead><tbody><tr><td>Reach of TA</td><td>5</td><td>9 (1.2M)</td><td>6 (500K)</td><td>8 (750K)</td><td>5 (300K)</td><td>7 (900K)</td></tr><tr><td>Engagement Rate</td><td>1</td><td>8 (6.5%)</td><td>5 (3.9%)</td><td>6 (4.3%)</td><td>7 (5.1%)</td><td>9 (8.2%)</td></tr><tr><td>Preferred Platforms</td><td>0.1</td><td>9 (IG, TikTok)</td><td>7 (Twitter, LI)</td><td>8 (YT, IG)</td><td>6 (FB, IG)</td><td>9 (TikTok, IG)</td></tr><tr><td>Content Style</td><td>0.1</td><td>8 (Workout)</td><td>8 (Tech)</td><td>7 (Vlogs)</td><td>8 (Food)</td><td>9 (Travel)</td></tr><tr><td>Frequency</td><td>0.1</td><td>10 (Daily)</td><td>6 (Bi-weekly)</td><td>7 (Weekly)</td><td>10 (Daily)</td><td>10 (Daily)</td></tr><tr><td>Tone</td><td>0.05</td><td>9 (Motivational)</td><td>7 (Analytical)</td><td>8 (Friendly)</td><td>7 (Honest)</td><td>8 (Adventurous)</td></tr><tr><td>Expertise</td><td>0.1</td><td>10 (Certified)</td><td>9 (Consultant)</td><td>7 (Beauty)</td><td>10 (Culinary)</td><td>8 (Travel)</td></tr><tr><td>Trustworthiness</td><td>0.1</td><td>10 (High)</td><td>9 (High)</td><td>7 (Moderate)</td><td>10 (High)</td><td>8 (Moderate)</td></tr><tr><td>TA Alignment</td><td>0.05</td><td>9 (Fitness)</td><td>8 (Tech)</td><td>7 (Youth)</td><td>9 (Food)</td><td>9 (Adventure)</td></tr><tr><td>Cultural Suitability</td><td>0.05</td><td>9 (High)</td><td>7 (Moderate)</td><td>7 (Moderate)</td><td>9 (High)</td><td>9 (High)</td></tr><tr><td><strong>Overall Score</strong></td><td><strong>1.0</strong></td><td><strong>8.9</strong></td><td><strong>7.2</strong></td><td><strong>7.0</strong></td><td><strong>8.2</strong></td><td><strong>8.3</strong></td></tr></tbody></table><h3 id="factors-considered" tabindex="-1">Factors Considered <a class="header-anchor" href="#factors-considered" aria-label="Permalink to &quot;Factors Considered&quot;">​</a></h3><p><strong>Relevance to Target Audience</strong>: Must have a substantial and active following among the target audience. Their content should resonate and align with the interests, values, and cultural context of the audience.</p><p><strong>Credibility and Trust</strong>: Should be seen as trustworthy and authoritative. Their message should carry weight due to perceived expertise, authenticity, or reliability.</p><p><strong>Alignment with Desired Behavior</strong>: The influencer&#39;s existing behavior, messaging, and personal brand should align with the objectives and desired behavior changes.</p><p><strong>Reach and Engagement</strong>: Should possess a significant number of followers (or targeted reach within a niche). Engagement rate (likes, comments, shares) should be high, indicating active participation from their audience.</p><p><strong>Consistency</strong>: Must regularly produce content that supports the desired objectives. Their messaging should remain consistent and not contradict the intended objectives.</p><p><strong>Platform Suitability</strong>: Their primary social media platform should match the one most used by the target audience.</p><p><strong>Potential Partnerships</strong>: Willingness to produce their own ads. Past partnerships or collaborations can indicate flexibility and openness.</p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li>Ware III, Charles M., and Aaron Siebenaller. &quot;IDENTIFYING INFLUENCERS FOR PSYOP.&quot; <em>NPS</em>, 2021.</li><li>Wingate, Alexander R., Kyle M. Gerik, and John A. Benson. &quot;ANALYZING KEY COMMUNICATORS.&quot; <em>NPS</em>, 2022.</li></ul>',31)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
